// ===== validate input + build Gemini translate+spell request =====
// แอป (artwork_check/translate.py) ส่ง POST JSON {"lines": [...]}
const item = $input.first().json;
const body = item.body ?? item;

let lines = body.lines;
let valid = true;
let error = '';

if (!Array.isArray(lines)) {
  valid = false;
  error = "missing JSON field 'lines' (array of strings)";
  lines = [];
} else {
  lines = lines.map((l) => (l == null ? '' : String(l)));
  if (lines.length === 0) { valid = false; error = "'lines' is empty"; }
  if (lines.length > 400) {
    valid = false;
    error = `too many lines: ${lines.length} (limit 400)`;
  }
}

// ── optional: คำที่ dict layer ฝั่งแอปฟ้องไว้แล้ว ให้โมเดล "ตัดสิน" รายคำ
// (แอปรุ่นเก่าไม่ส่ง field นี้ → suspects ว่าง → prompt เหมือนเดิมทุกตัวอักษร)
let checkWords = body.check_words;
if (!Array.isArray(checkWords)) checkWords = [];
checkWords = checkWords.map((ws) => Array.isArray(ws)
  ? ws.map((w) => (w == null ? '' : String(w).trim())).filter(Boolean)
  : []);
while (checkWords.length < lines.length) checkWords.push([]);
checkWords = checkWords.slice(0, lines.length);
const suspects = [];
checkWords.forEach((ws, i) => {
  if (ws.length) {
    suspects.push('  - in line ' + (i + 1) + ' ' +
      JSON.stringify(lines[i]) + ': ' + ws.join(', '));
  }
});

const PROMPT = [
  'You are a STRICT proofreading assistant for printed food-packaging labels.',
  'You receive a JSON array of text lines exactly as they appear on the',
  'artwork, in mixed languages (Arabic, Spanish, Thai, English, ...).',
  '',
  'This is an INSPECTION, not a translation for easy reading. Faithfulness to',
  'what is ACTUALLY printed matters more than making the result look correct.',
  '',
  'Do TWO independent things:',
  '',
  '1) TRANSLATE every line to English -> array "translations":',
  '   - One entry per input line, in the SAME order, SAME length as input.',
  '   - Translate ONLY what is actually written. NEVER complete, expand,',
  '     auto-correct, or guess missing / cut-off letters.',
  '   - If a line is truncated or a fragment (e.g. "Ingredi", "Prod"), a',
  '     misspelling, or otherwise broken, translate it LITERALLY as the',
  '     broken fragment it is. Do NOT turn it into the intended full word.',
  '   - If a line is already English, return it UNCHANGED (including any',
  '     truncation or misspelling).',
  '   - If a line is only digits / codes / units (e.g. "16785", "200 gm",',
  '     "70%"), return it unchanged.',
  '   - Concise, faithful meaning. No notes, no commentary.',
  '',
  '2) SPELL / COMPLETENESS CHECK on the ORIGINAL lines -> array "spell":',
  '   The input is an ORDERED list of separate OCR lines from ONE artwork;',
  '   long sentences and paragraphs are naturally split across several',
  '   consecutive lines. Judge each line as part of that whole document,',
  '   NOT in isolation.',
  '   Return an entry ONLY for lines that deserve a human look in their own',
  '   language: a real typo / misspelling, a genuinely truncated / cut-off',
  '   word (see the strict rule below), or a correct regional spelling',
  '   variant (see "variant" below).',
  '   Each entry has four fields:',
  '     "original"   = an EXACT, character-for-character copy of the input',
  '                    line you are flagging (do NOT paraphrase or translate',
  '                    it; it must match one of the input lines verbatim).',
  '     "suggestion" = the likely correct / complete line (MUST differ from',
  '                    "original").',
  '     "kind"       = exactly one of:',
  '                    "typo"      — misspelled / swapped / missing letters;',
  '                    "truncated" — a word physically cut off at the EDGE',
  '                    of the artwork whose continuation does NOT appear on',
  '                    any following input line (e.g. "Ingredi" alone, with',
  '                    no "...ents" anywhere after it);',
  '                    "variant"   — the word is CORRECT, but it is a',
  '                    regional spelling (e.g. British "fibre" / American',
  '                    "fiber", "colour" / "color"). A variant is NOT an',
  '                    error — report it only so the reviewer can confirm',
  '                    the spelling matches the target market, and put the',
  '                    other regional form in "suggestion".',
  '     "reason"     = a SHORT explanation in THAI (one sentence, at most',
  '                    ~15 words) of why this line is flagged, e.g.',
  '                    "fibre เป็นการสะกดแบบ British English ส่วน American ใช้ fiber"',
  '                    or "คำถูกตัดปลาย น่าจะเป็น Ingredients".',
  '   - LINE-WRAP IS NOT TRUNCATION (most important rule). If a line ends',
  '     mid-word or mid-sentence but its continuation appears on the NEXT',
  '     input line(s), that is normal text wrapping — do NOT flag it and',
  '     never mark it "truncated". Only "truncated" when the continuation',
  '     is missing from the ENTIRE input.',
  '   - Never build a "suggestion" by borrowing words from another line.',
  '     The suggestion must be a correction of THIS line alone.',
  '   - Flag ONLY when fairly confident. Do NOT flag: correct standard',
  '     words, brand names, product names, valid loanwords, standard',
  '     abbreviations, units, codes, or pure numbers.',
  '   - If NO line needs review, return "spell": [] (an empty array).',
  '   - This is advisory for a human reviewer; it NEVER decides pass/fail.',
].join('\n');

// ── รายการคำที่ต้อง "ตัดสิน" เป็นรายคำ (จาก dict layer ฝั่งแอป) ──
// เหตุผล: การให้โมเดลสแกนหาคำผิดเองแบบปลายเปิดพลาด typo แบบสลับอักษร
// ("Phosphours") เพราะ LLM อ่านเป็น token ไม่ใช่ตัวอักษร — งานตัดสินคำ
// ที่ระบุชื่อมาแล้วแม่นกว่ามาก
const SUSPECTS = suspects.length ? [
  '',
  'MANDATORY ADJUDICATION LIST:',
  'A deterministic dictionary layer has ALREADY flagged the words below',
  '(they were found in no dictionary). For EACH listed word you MUST',
  'explicitly decide by comparing it LETTER BY LETTER against the closest',
  'real word — watch for swapped, missing or doubled letters, e.g.',
  '"Phosphours" vs "Phosphorus" (r/u swapped), "Cude" vs "Crude"',
  '(missing r):',
  '  - if it is a misspelling: you MUST return a spell entry for that',
  '    line (kind "typo") with the corrected line as "suggestion";',
  '  - if it is physically cut off: spell entry with kind "truncated";',
  '  - if it is a genuinely correct word / brand / proper noun /',
  '    loanword: return NO entry for it.',
  'Never skip a listed word. "line N" is the 1-based position in INPUT',
  'LINES; "original" in your entry must still be the verbatim line text.',
  'The list:',
  ...suspects,
].join('\n') : '';

const responseSchema = {
  type: 'OBJECT',
  properties: {
    translations: {
      type: 'ARRAY',
      description: 'English translation, one entry per input line, same order and length as the input.',
      items: { type: 'STRING' },
    },
    spell: {
      type: 'ARRAY',
      description: 'Only the input lines that are misspelled, truncated, or regional spelling variants. Empty array if no line needs review.',
      items: {
        type: 'OBJECT',
        properties: {
          original: { type: 'STRING', description: 'Exact verbatim copy of the flagged input line.' },
          suggestion: { type: 'STRING', description: 'The corrected / completed line (or the other regional spelling); must differ from original.' },
          kind: { type: 'STRING', enum: ['typo', 'truncated', 'variant'], description: 'typo = misspelling, truncated = cut-off word, variant = correct regional spelling.' },
          reason: { type: 'STRING', description: 'Short Thai explanation (one sentence, <= ~15 words) of why this line is flagged.' },
        },
        required: ['original', 'suggestion', 'kind', 'reason'],
      },
    },
  },
  required: ['translations', 'spell'],
};

const geminiRequest = !valid ? null : {
  contents: [{
    role: 'user',
    parts: [
      { text: PROMPT + SUSPECTS },
      { text: 'INPUT LINES (JSON array):\n' + JSON.stringify(lines) },
    ],
  }],
  generationConfig: {
    temperature: 0,
    topP: 1,
    // sparse spell means output is bounded by real content; scale the cap
    // with line count instead of a flat 65536. (160/line leaves room for
    // the per-finding Thai "reason" text.)
    maxOutputTokens: Math.min(65536, 1024 + lines.length * 160),
    responseMimeType: 'application/json',
    responseSchema,
    thinkingConfig: { thinkingBudget: 0 },
  },
};

// ส่ง lines + line_count ต่อให้ node parse ใช้ match ข้อความกลับเป็นบรรทัด
return [{
  json: {
    valid,
    error,
    line_count: lines.length,
    lines,
    gemini_request: geminiRequest,
  },
}];

// ===== parse Gemini response -> {"translations":[...], "spell":[...]} =====
const r = $input.first().json;
if (r.error) throw new Error(`Gemini API error: ${JSON.stringify(r.error)}`);

// ── ดึง input เดิมจาก node validate เพื่อ align ความยาว + match ข้อความ
const meta = $('Code in JavaScript2').first().json;
const srcLines = Array.isArray(meta.lines) ? meta.lines : [];
const n = Number.isInteger(meta.line_count) ? meta.line_count : srcLines.length;

// ── รวมข้อความตอบกลับจาก Gemini แล้วถอด ```json fences
const cand = (r.candidates ?? [])[0] ?? {};
const raw = ((cand.content ?? {}).parts ?? [])
  .map((p) => p.text ?? '').join('\n').trim();

let s = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let parsed = null;
try { parsed = JSON.parse(s); }
catch (e) {
  // เผื่อโมเดลแถมข้อความหุ้ม JSON: คว้าก้อน {...} ที่ใหญ่ที่สุด
  const i = s.indexOf('{'), j = s.lastIndexOf('}');
  if (i >= 0 && j > i) {
    try { parsed = JSON.parse(s.slice(i, j + 1)); } catch (e2) {}
  }
}

const warnings = [];
const norm = (v) => v.toString().trim().toLowerCase();

// ── translations: รับได้ทั้ง {translations:[...]} และ array เปล่าๆ
let translations = [];
if (parsed && Array.isArray(parsed.translations)) {
  translations = parsed.translations;
} else if (Array.isArray(parsed)) {
  translations = parsed;
} else {
  warnings.push('model did not return a translations array');
}
translations = translations.map((t) => (t == null ? '' : String(t)));

// ── spell: sparse [{original, suggestion, kind, reason}]
//    -> dense per-line [{flagged, suggestion, kind, reason}]
//    match ด้วยข้อความ "original" ที่โมเดลคัดลอกมา (ไม่ใช่ index ที่โมเดลนับพลาด)
//    => suggestion ไปแปะได้เฉพาะบรรทัดที่ตรงข้อความจริงเท่านั้น กันบั๊ก misalignment.
const CLEAN_SPELL = () => ({ flagged: false, suggestion: null,
                             kind: null, reason: null });
const KINDS = new Set(['typo', 'truncated', 'variant']);
let spell = null;
if (parsed && Array.isArray(parsed.spell)) {
  spell = Array.from({ length: n }, CLEAN_SPELL);
  const byText = new Map();               // normalized source line -> [indices]
  for (let i = 0; i < n; i++) {
    const k = norm(srcLines[i] != null ? srcLines[i] : '');
    if (!byText.has(k)) byText.set(k, []);
    byText.get(k).push(i);
  }
  for (const e of parsed.spell) {
    if (!e || typeof e !== 'object' || Array.isArray(e)) continue;
    const orig = e.original != null ? String(e.original) : '';
    let suggestion = e.suggestion != null ? String(e.suggestion) : null;
    if (!orig || suggestion == null) continue;
    if (norm(suggestion) === norm(orig)) continue;   // ไม่ได้แก้อะไรจริง
    // advisory extras — สตริงสั้นอธิบายเหตุผล + ชนิดของ finding
    const kind = KINDS.has(e.kind) ? e.kind : null;
    const reason = (e.reason != null && String(e.reason).trim())
      ? String(e.reason).trim() : null;
    const idxs = byText.get(norm(orig));
    if (!idxs || !idxs.length) continue;             // ข้อความไม่ตรงบรรทัดไหนเลย -> ทิ้ง (กัน garbage)
    for (const i of idxs) spell[i] = { flagged: true, suggestion, kind, reason };
  }
} else if (parsed) {
  warnings.push('model did not return a spell array');
}

// ── บังคับความยาว translations ให้ตรงจำนวนบรรทัด + ให้ spell เป็น dense เสมอ
if (n > 0) {
  while (translations.length < n) translations.push('');
  translations.length = n;
}
if (spell === null) {
  spell = Array.from({ length: Math.max(n, 0) }, CLEAN_SPELL);
}

const warning = warnings.length ? warnings.join('; ') : undefined;

return [{
  json: {
    translations,
    spell,
    ...(warning ? { warning } : {}),
    usage: r.usageMetadata ?? null,
  },
}];
